head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
scwin.gNDV_NOTI_NO;
scwin.gNOTI_PROCS_STAT_CD; // 00:처리중, 10:검토, 20:승인
scwin.gPOP_GB; // N:입력, R:상세보기, P:검토/승인

scwin.gEmpNo = js_emp_no;
scwin.vScrenID = 'ULDSTF00002.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_setCode = function() {
    dts_single.DataID = "/NightNoti.do?method=getNotiEmptyHeader";
    dts_single.Reset();
    dts_single.insertRow();
};
scwin.initPage = function() {
    $c.stf.showObj(panel_debug, false);
    scwin.fn_setCode();
    scwin.gNDV_NOTI_NO = $c.stf.getQuery(frame.srcUrl, "NDV_NOTI_NO");
    scwin.gNOTI_PROCS_STAT_CD = $c.stf.getQuery(frame.srcUrl, "NOTI_PROCS_STAT_CD");
    scwin.gPOP_GB = $c.stf.getQuery(frame.srcUrl, "POP_GB");
    scwin.fn_search();
    if (scwin.gPOP_GB == "N") {
        $c.stf.showObj(panel_1, true);
        $c.stf.showObj(panel_2, false);
        $c.stf.showObj(panel_3, false);
        $c.stf.setObjectValue(txb_NDV_NOTI_TITLE, "(야간파생상품시장 공지)");
    } else if (scwin.gPOP_GB == "R") {
        $c.stf.showObj(panel_1, false);
        $c.stf.showObj(panel_2, false);
        $c.stf.showObj(panel_3, false);
    } else if (scwin.gPOP_GB == "P") {
        if (scwin.gNOTI_PROCS_STAT_CD == "00") {
            $c.stf.showObj(panel_1, false);
            $c.stf.showObj(panel_2, true);
            $c.stf.showObj(panel_3, false);
        } else if (scwin.gNOTI_PROCS_STAT_CD == "10") {
            $c.stf.showObj(panel_1, false);
            $c.stf.showObj(panel_2, false);
            $c.stf.showObj(panel_3, true);
        }
    }
    scwin.fn_getNowTime();
};
scwin.fn_search = function() {
    var url = "/NightNoti.do?method=readNotiDtl" + "&NDV_NOTI_NO=" + scwin.gNDV_NOTI_NO + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_NdvNotiData.DataID = encodeURI(url);
    dts_NdvNotiData.reset();
};
scwin.fn_CheckValue = function() {
    if ($c.stf.getObjectValue(txb_NDV_NOTI_TITLE) == "") {
        $c.win.alert("[제목]을 입력하세요.");
        txb_NDV_NOTI_TITLE.focus();
        return false;
    }
    if (txa_NDV_NOTI_CONTN.Text == "") {
        $c.win.alert("[내용]을 입력하세요.");
        txa_NDV_NOTI_CONTN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_NDV_NOTI_TITLE) != "") {
        if (!$c.stf.checkMaxLength(txb_NDV_NOTI_TITLE, 1000, "제목")) return false;
    }
    return true;
};
scwin.fn_getNowTime = function() {
    var url = "/NightNoti.do?method=getNowTime";
    dts_now.DataID = encodeURI(url);
    dts_now.reset();
};
scwin.fn_save = function() {
    if (scwin.fn_CheckValue()) {
        scwin.fn_trs("I");
    }
};
scwin.fn_update = function() {
    if (scwin.fn_CheckValue()) {
        scwin.fn_trs("U");
    }
};
scwin.fn_delete = function() {
    scwin.fn_trs("D");
};
scwin.fn_review = function() {
    if (scwin.fn_CheckValue()) {
        scwin.fn_trs("R");
    }
};
scwin.fn_approval = function() {
    // 승인가능시간 (20:00 ~ 07:30)
    scwin.fn_getNowTime();
    //alert(getObjectValue(txb_nowtime));

    if ($c.stf.getObjectValue(txb_nowtime) < "200000" && $c.stf.getObjectValue(txb_nowtime) >= "073000") {
        $c.win.alert("승인가능시간 (20:00 ~ 07:30)");
        return false;
    }
    if (scwin.fn_CheckValue()) {
        scwin.fn_trs("A");
    }
};
scwin.fn_reject = function() {
    if (scwin.fn_CheckValue()) {
        scwin.fn_trs("J");
    }
};
scwin.fn_trs = function(trIdx) {
    var gJob;
    var gTrsCd;
    if (trIdx == "I") {
        gJob = '저장';
        gTrsCd = SCREN_PROCS_TP_CD_02;
    } else if (trIdx == "U") {
        gJob = '수정';
        gTrsCd = SCREN_PROCS_TP_CD_03;
    } else if (trIdx == "D") {
        gJob = '삭제';
        gTrsCd = SCREN_PROCS_TP_CD_04;
    } else if (trIdx == "R") {
        gJob = '검토';
        gTrsCd = SCREN_PROCS_TP_CD_03;
    } else if (trIdx == "A") {
        gJob = '승인';
        gTrsCd = SCREN_PROCS_TP_CD_03;
    } else if (trIdx == "J") {
        gJob = '반려';
        gTrsCd = SCREN_PROCS_TP_CD_03;
    }
    var vAnswer = window.confirm(gJob + " 하시겠습니까?");
    if (vAnswer == true) {
        //dts_single.NameString(1, "PROCS_GB") = trIdx;
        dts_single.setCellData(1, "NDV_NOTI_NO", $c.stf.getObjectValue(txb_NDV_NOTI_NO));
        dts_single.setCellData(1, "LD_MKT_TP_CD", "3"); //파생
        dts_single.setCellData(1, "NDV_NOTI_TITLE", $c.stf.getObjectValue(txb_NDV_NOTI_TITLE));
        dts_single.setCellData(1, "NDV_NOTI_CONTN", txa_NDV_NOTI_CONTN.Text);
        dts_single.setCellData(1, "EMP_NO", scwin.gEmpNo);
        trs_Save.Action = "/NightNoti.do?method=procNotiDtl&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + gTrsCd;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_single)";
        trs_Save.Parameters = "PROCS_GB=" + trIdx;
        trs_Save.Post();
    }
};



//new line
scwin.fn_newLine = function(str) {
    if (str == "") return "";
    return str.replace(/\r\n/g, "<br/>");
};
scwin.gform_onload = function() {
    scwin.initPage();
};
scwin.dts_NdvNotiData_OnLoadCompleted = function(rowcount) {
    if (dts_NdvNotiData.errorMsg) {
        $c.win.alert(dts_NdvNotiData.errorMsg);
    } else {
        $c.stf.setObjectValue(txb_REVWR_EMP_NM, dts_NdvNotiData.getCellData(1, "REVWR_EMP_NM"));
        $c.stf.setObjectValue(txb_REVW_DDTM, dts_NdvNotiData.getCellData(1, "REVW_DDTM"));
        $c.stf.setObjectValue(txb_APPROVR_EMP_NM, dts_NdvNotiData.getCellData(1, "APPROVR_EMP_NM"));
        $c.stf.setObjectValue(txb_APPROV_DDTM, dts_NdvNotiData.getCellData(1, "APPROV_DDTM"));
        $c.stf.setObjectValue(txb_NDV_NOTI_TITLE, dts_NdvNotiData.getCellData(1, "NDV_NOTI_TITLE"));
        //setObjectValue(txb_NDV_NOTI_CONTN, dts_NdvNotiData.NameString(1, "NDV_NOTI_CONTN"));
        txa_NDV_NOTI_CONTN.Text = dts_NdvNotiData.getCellData(1, "NDV_NOTI_CONTN");
    }
};
scwin.dts_NdvNotiData_OnLoadError = function() {
    $c.stf.alert_error(dts_NdvNotiData);
};
scwin.dts_now_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_now_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(txb_nowtime, dts_now.getCellData(1, 'NOW_TIME'));
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_save();
};
scwin.btn_Update_onclick = function() {
    scwin.fn_update();
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_delete();
};
scwin.btn_Revw_onclick = function() {
    scwin.fn_review();
};
scwin.btn_Approvr_onclick = function() {
    scwin.fn_approval();
};
scwin.btn_Rjct_onclick = function() {
    scwin.fn_reject();
};
scwin.trs_Save_OnFail = function() {
    var msg = $c.stf.getMessageParam("MSG-0002", "");
    $c.win.alert(msg);
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-0001", "");
    $c.win.alert(msg);
    $c.frame.path("../").fn_Search();
    await $c.frame.CloseFrame();
};
